+// earlierAttempts adds one detail line naming the failed attempts before the one that ended
+// the call, when any of them differs from it.
+func earlierAttempts(err error, earlier []string, last string) error {
+	e, ok := err.(*sys.Error)
+	if !ok {
+		return err
+	}
+	differs := false
+	parts := make([]string, len(earlier))
+	for i, d := range earlier {
+		differs = differs || d != last
+		parts[i] = itoa(int64(i+1)) + " " + d
+	}
+	if differs {
+		e.Lines = append(e.Lines, "earlier attempts: "+strings.Join(parts, "; "))
+	}
+	return e
+}
